  'philips_hue_light.omni_driver.json': r'''
{
  "schemaVersion": 1,
  "id": "philips_hue_light",
  "name": "Philips Hue light (bridge, local REST API v1)",
  "category": "lighting",
  "icon": "lightbulb",
  "transport": { "type": "http", "port": 80, "authErrorTypes": [1] },
  "discovery": [{ "method": "mdns", "service": "_hue._tcp", "idTxt": "bridgeid", "usePort": false }],
  "pairing": { "method": "hue_bridge" },
  "settings": [
    { "key": "lightId", "label": "Light number on the bridge (1, 2, ...)", "help": "The light's number on the Hue bridge: 1 for the first light added, then 2 and so on.\nIn the Hue app open Settings, Lights, and count down the list, or let OmniFlow find the lights on the bridge." },
    { "key": "username", "label": "Bridge username, stored by pairing after the link button is pressed", "secret": true, "help": "The key the bridge gives OmniFlow when you press its round link button during pairing. You never type it. It stays on this phone." },
    { "key": "gamut", "label": "Colour gamut the light reports as capabilities.control.colorgamuttype: A, B or C (the default)", "help": "Which range of colours the bulb can show: A, B or C. Leave it empty for C, which newer bulbs use.\nIf colours look wrong on an older bulb, try A or B." }
  ],
  "setup": ["pair", "configure:lightId"],
  "statePoll": { "intervalSeconds": 30, "command": { "path": "/api/:secret:username/lights/{{device.lightId}}" }, "jsonPath": "$.state" },
  "reliability": { "timeoutMs": 3000, "retries": 1 },
  "capabilities": [
    {
      "id": "power",
      "type": "toggle",
      "label": "Power",
      "command": { "method": "PUT", "path": "/api/:secret:username/lights/{{device.lightId}}/state", "body": { "on": "{{value}}" } },
      "stateJsonPath": "$.on"
    },
    {
      "id": "brightness",
      "type": "level",
      "label": "Brightness",
      "params": { "value": { "type": "number", "integer": true, "min": 1, "max": 254 } },
      "command": { "method": "PUT", "path": "/api/:secret:username/lights/{{device.lightId}}/state", "body": { "on": true, "bri": "{{value}}" } },
      "stateJsonPath": "$.bri"
    },
    {
      "id": "color_temp",
      "type": "level",
      "label": "White temperature in mireds (153 cool to 500 warm)",
      "params": { "value": { "type": "number", "integer": true, "min": 153, "max": 500, "unit": "mired" } },
      "command": { "method": "PUT", "path": "/api/:secret:username/lights/{{device.lightId}}/state", "body": { "on": true, "ct": "{{value}}" } },
      "stateJsonPath": "$.ct"
    },
    {
      "id": "rgb",
      "type": "color_rgb",
      "label": "Colour, sent as xy inside the light's gamut",
      "params": { "brightness": { "type": "number", "integer": true, "min": 1, "max": 254, "optional": true } },
      "derive": "hue_xy",
      "command": {
        "method": "PUT",
        "path": "/api/:secret:username/lights/{{device.lightId}}/state",
        "body": { "on": true, "xy": "{{xy}}", "bri": "{{brightness|state.bri|254}}" }
      },
      "stateJsonPath": "$.xy"
    }
  ]
}
''',
  'philips_wiz_udp.omni_driver.json': r'''
{
  "schemaVersion": 1,
  "id": "philips_wiz_udp",
  "name": "Philips WiZ Light (local UDP)",
  "category": "lighting",
  "icon": "lightbulb",
  "transport": { "type": "udp", "port": 38899, "listenPort": 38900, "payload": "json", "matchMethod": true },
  "discovery": [
    {
      "method": "udp_broadcast",
      "port": 38899,
      "probe": { "method": "registration", "params": { "phoneMac": "AAAAAAAAAAAA", "register": false, "phoneIp": "1.2.3.4", "id": "1" } },
      "matchJsonPath": "$.result.mac",
      "idJsonPath": "$.result.mac"
    }
  ],
  "statePush": { "method": "syncPilot", "jsonPath": "$.params" },
  "statePoll": { "intervalSeconds": 60, "command": { "method": "getPilot", "params": {} }, "jsonPath": "$.result" },
  "reliability": { "timeoutMs": 500, "retries": 2 },
  "capabilities": [
    {
      "id": "power",
      "type": "toggle",
      "label": "Power",
      "command": { "id": 1, "method": "setState", "params": { "state": "{{value}}" } },
      "stateJsonPath": "$.state"
    },
    {
      "id": "brightness",
      "type": "level",
      "label": "Brightness",
      "params": { "value": { "type": "number", "integer": true, "min": 10, "max": 100, "unit": "%" } },
      "command": { "id": 1, "method": "setPilot", "params": { "state": true, "dimming": "{{value}}" } },
      "stateJsonPath": "$.dimming"
    },
    {
      "id": "color_temp",
      "type": "color_temp",
      "label": "White temperature",
      "params": {
