      "stateJsonPath": "$.temp"
    },
    {
      "id": "rgb",
      "type": "color_rgb",
      "label": "Colour",
      "params": { "brightness": { "type": "number", "integer": true, "min": 10, "max": 100, "optional": true } },
      "command": {
        "id": 1,
        "method": "setPilot",
        "params": { "state": true, "r": "{{r}}", "g": "{{g}}", "b": "{{b}}", "dimming": "{{brightness|state.dimming|100}}" }
      }
    }
  ]
}
''',
