    { "key": "certSha256", "label": "Pinned TLS certificate SHA-256 (stored on first connect)", "secret": true, "help": "A fingerprint of the TV's security certificate, saved the first time OmniFlow connects, so another device cannot pretend to be the TV. You never type it." }
  ],
  "setup": ["pair"],
  "reliability": { "timeoutMs": 3000, "retries": 1 },
  "capabilities": [
    {
      "id": "remote",
      "type": "dpad_remote",
      "label": "Remote",
      "command": {
        "key": "{{value}}",
        "keyMap": {
          "up": "KEY_UP",
          "down": "KEY_DOWN",
          "left": "KEY_LEFT",
          "right": "KEY_RIGHT",
          "ok": "KEY_ENTER",
          "back": "KEY_RETURN",
          "home": "KEY_HOME"
        }
      }
    },
    { "id": "volume_up", "type": "action", "label": "Volume up", "command": { "key": "KEY_VOLUP" } },
    { "id": "volume_down", "type": "action", "label": "Volume down", "command": { "key": "KEY_VOLDOWN" } },
    { "id": "mute", "type": "action", "label": "Mute", "command": { "key": "KEY_MUTE" } },
    { "id": "power", "type": "action", "label": "Power key", "command": { "key": "KEY_POWER" } },
    {
      "id": "launch_app",
      "type": "action",
      "label": "Launch app",
      "params": { "app": { "type": "string", "pattern": "[A-Za-z0-9][A-Za-z0-9._]{1,127}" } },
      "command": { "launch": "{{app}}", "actionType": "DEEP_LINK" }
    }
  ]
}
''',
  'shelly_gen1_relay.omni_driver.json': r'''
