  'sonos_upnp.omni_driver.json': r'''
{
  "schemaVersion": 1,
  "id": "sonos_upnp",
  "name": "Sonos speaker (local UPnP on port 1400)",
  "category": "media",
  "icon": "speaker",
  "transport": { "type": "http", "port": 1400, "reply": "xml" },
  "discovery": [{ "method": "ssdp", "st": "urn:schemas-upnp-org:device:ZonePlayer:1", "idHeader": "usn" }],
  "statePoll": {
    "intervalSeconds": 15,
    "command": {
      "method": "POST",
      "path": "/MediaRenderer/AVTransport/Control",
      "soap": { "service": "urn:schemas-upnp-org:service:AVTransport:1", "action": "GetTransportInfo", "args": { "InstanceID": 0 } }
    },
    "also": [
      {
        "command": {
          "method": "POST",
          "path": "/MediaRenderer/RenderingControl/Control",
          "soap": { "service": "urn:schemas-upnp-org:service:RenderingControl:1", "action": "GetVolume", "args": { "InstanceID": 0, "Channel": "Master" } }
        }
      },
      {
        "command": {
          "method": "POST",
          "path": "/MediaRenderer/RenderingControl/Control",
          "soap": { "service": "urn:schemas-upnp-org:service:RenderingControl:1", "action": "GetMute", "args": { "InstanceID": 0, "Channel": "Master" } }
        }
      }
    ]
  },
  "reliability": { "timeoutMs": 2000, "retries": 1 },
  "capabilities": [
    {
      "id": "play",
      "type": "action",
      "label": "Play",
      "command": {
        "method": "POST",
        "path": "/MediaRenderer/AVTransport/Control",
        "soap": { "service": "urn:schemas-upnp-org:service:AVTransport:1", "action": "Play", "args": { "InstanceID": 0, "Speed": 1 } }
      }
    },
    {
      "id": "pause",
      "type": "action",
      "label": "Pause",
      "command": {
        "method": "POST",
        "path": "/MediaRenderer/AVTransport/Control",
        "soap": { "service": "urn:schemas-upnp-org:service:AVTransport:1", "action": "Pause", "args": { "InstanceID": 0 } }
      }
    },
    {
      "id": "next",
      "type": "action",
      "label": "Next track",
      "command": {
        "method": "POST",
        "path": "/MediaRenderer/AVTransport/Control",
        "soap": { "service": "urn:schemas-upnp-org:service:AVTransport:1", "action": "Next", "args": { "InstanceID": 0 } }
      }
    },
    {
      "id": "previous",
      "type": "action",
      "label": "Previous track",
      "command": {
        "method": "POST",
        "path": "/MediaRenderer/AVTransport/Control",
        "soap": { "service": "urn:schemas-upnp-org:service:AVTransport:1", "action": "Previous", "args": { "InstanceID": 0 } }
      }
    },
    {
      "id": "volume",
      "type": "level",
      "label": "Volume",
      "params": { "value": { "type": "number", "integer": true, "min": 0, "max": 100 } },
      "command": {
        "method": "POST",
        "path": "/MediaRenderer/RenderingControl/Control",
        "soap": {
          "service": "urn:schemas-upnp-org:service:RenderingControl:1",
          "action": "SetVolume",
          "args": { "InstanceID": 0, "Channel": "Master", "DesiredVolume": "{{value}}" }
        }
      },
      "stateJsonPath": "$.CurrentVolume"
    },
    {
      "id": "mute",
      "type": "toggle",
      "label": "Mute",
      "onOff": [1, 0],
      "command": {
        "method": "POST",
        "path": "/MediaRenderer/RenderingControl/Control",
        "soap": {
          "service": "urn:schemas-upnp-org:service:RenderingControl:1",
          "action": "SetMute",
          "args": { "InstanceID": 0, "Channel": "Master", "DesiredMute": "{{value}}" }
        }
      },
      "stateJsonPath": "$.CurrentMute"
    },
    {
      "id": "playback",
      "type": "sensor",
      "label": "Playback (PLAYING, PAUSED_PLAYBACK, STOPPED or TRANSITIONING)",
      "stateJsonPath": "$.CurrentTransportState",
      "values": ["PLAYING", "PAUSED_PLAYBACK", "STOPPED", "TRANSITIONING"]
    }
  ]
}
''',
  'tasmota_mqtt.omni_driver.json': r'''
{
  "schemaVersion": 1,
  "id": "tasmota_mqtt",
  "name": "Tasmota device (MQTT)",
  "category": "power",
  "icon": "power",
  "transport": { "type": "mqtt", "port": 1883 },
  "settings": [
    { "key": "topic", "label": "Tasmota topic (Configuration, MQTT, Topic)", "help": "The device's MQTT topic, such as tasmota_A1B2C3.\nOpen the device's web page, then Configuration, MQTT, and copy Topic." },
    { "key": "username", "label": "Broker user", "help": "The user name your MQTT broker asks for. Leave it empty if the broker takes anyone. It is in the broker's settings, for example the Mosquitto add-on's Logins in Home Assistant." },
    { "key": "password", "label": "Broker password (one per broker and user, shared by its devices)", "secret": true, "help": "The password for the broker user. It stays on this phone and is never shown again. Leave it empty if the broker has no password." }
  ],
  "setup": ["configure:topic", "configure:username?", "secret:password?"],
  "statePush": {
    "topics": [
      { "topic": "stat/{{device.topic}}/RESULT" },
      { "topic": "tele/{{device.topic}}/STATE" },
      { "topic": "stat/{{device.topic}}/POWER", "key": "POWER" }
    ],
    "refresh": { "topic": "cmnd/{{device.topic}}/STATE", "payload": "" }
  },
  "reliability": { "timeoutMs": 3000, "retries": 0 },
  "capabilities": [
    {
      "id": "power",
      "type": "toggle",
      "label": "Power",
      "onOff": ["ON", "OFF"],
      "command": { "topic": "cmnd/{{device.topic}}/POWER", "payload": "{{value}}" },
      "stateJsonPath": "$.POWER"
    },
    {
      "id": "dimmer",
      "type": "level",
      "label": "Brightness",
      "params": { "value": { "type": "number", "integer": true, "min": 0, "max": 100, "unit": "%" } },
      "command": { "topic": "cmnd/{{device.topic}}/Dimmer", "payload": "{{value}}" },
      "stateJsonPath": "$.Dimmer"
    }
  ]
}
''',
  'tuya_light.omni_driver.json': r'''
{
  "schemaVersion": 1,
  "id": "tuya_light",
  "name": "Tuya smart bulb (local, colour data points 20 to 24)",
  "category": "lighting",
  "icon": "lightbulb",
  "transport": { "type": "tuya", "port": 6668, "version": "3.3" },
  "discovery": [{ "method": "tuya_broadcast", "idSetting": "devId" }],
  "settings": [
    { "key": "devId", "label": "Device id", "help": "The Tuya id of this device, about 20 letters and numbers. OmniFlow fills it in when it finds the device on your Wi-Fi.\nIf it is empty, open the device in the Smart Life or Wipro app, tap the pencil or the three dots, then Device information, and copy Virtual ID. The tinytuya wizard in the local key steps lists it too." },
    { "key": "localKey", "label": "Local key", "secret": true, "help": "A 16 character key the device uses to lock its messages. It is not in the Smart Life or Wipro app, so you get it once with a computer. It stays on this phone.\n1. Make sure the device works in the Smart Life app. A Wipro device works with Smart Life too: add it there, or keep the Wipro app if it lets you link below.\n2. On a computer, make a free account at iot.tuya.com. Open Cloud, Development, Create Cloud Project. Pick Smart Home and the data centre for your country (India for Wipro bought in India).\n3. In the project, open Devices, Link App Account, Add App Account. Scan the code with the Smart Life app (Me, then the scan icon). Your devices now show in the project.\n4. On the same computer, install Python, then run pip install tinytuya and python -m tinytuya wizard. Paste the Access ID and Access Secret from the project's Overview when it asks.\n5. The wizard prints each device with its id and local key. Copy the key for this device and paste it here.\nRemoving the device from the app and adding it again makes a new key, so run the wizard again after that. Close the Smart Life app while OmniFlow talks to the device, because it takes one connection at a time." },
    { "key": "version", "label": "Tuya protocol version: 3.3 (the default), 3.4 or 3.5", "help": "Which Tuya protocol the device speaks. Leave it empty for 3.3, which most plugs and bulbs use.\nIf commands time out, try 3.4, then 3.5. python -m tinytuya scan on a computer shows the version of each device." }
  ],
  "setup": ["configure:devId", "secret:localKey", "configure:version?"],
  "statePush": { "jsonPath": "$.dps" },
  "statePoll": { "intervalSeconds": 60, "command": { "cmd": "query" }, "jsonPath": "$.dps" },
  "reliability": { "timeoutMs": 1500, "retries": 1 },
  "capabilities": [
    {
      "id": "power",
      "type": "toggle",
      "label": "Power",
      "command": { "cmd": "control", "dps": { "20": "{{value}}" } },
      "stateJsonPath": "$['20']"
    },
    {
      "id": "brightness",
      "type": "level",
      "label": "White brightness (10 dim to 1000 full)",
      "params": { "value": { "type": "number", "integer": true, "min": 10, "max": 1000 } },
      "command": { "cmd": "control", "dps": { "20": true, "22": "{{value}}" } },
      "stateJsonPath": "$['22']"
    },
    {
      "id": "color_temp",
      "type": "level",
      "label": "White temperature (0 warm to 1000 cool)",
      "params": { "value": { "type": "number", "integer": true, "min": 0, "max": 1000 } },
      "command": { "cmd": "control", "dps": { "20": true, "21": "white", "23": "{{value}}" } },
      "stateJsonPath": "$['23']"
    },
    {
      "id": "rgb",
      "type": "color_rgb",
      "label": "Colour",
      "params": { "brightness": { "type": "number", "integer": true, "min": 10, "max": 1000, "optional": true } },
      "derive": "tuya_hsv",
      "command": { "cmd": "control", "dps": { "20": true, "21": "colour", "24": "{{hsv}}" } },
      "stateJsonPath": "$['24']"
    },
    {
      "id": "mode",
      "type": "text_command",
      "label": "Mode (white, colour, the bulb's scene, or music)",
      "params": { "value": { "type": "enum", "values": ["white", "colour", "scene", "music"] } },
      "command": { "cmd": "control", "dps": { "20": true, "21": "{{value}}" } },
      "stateJsonPath": "$['21']"
    }
  ]
}
''',
