  'zigbee2mqtt_device.omni_driver.json': r'''
{
  "schemaVersion": 1,
  "id": "zigbee2mqtt_device",
  "name": "Zigbee device (Zigbee2MQTT)",
  "category": "zigbee",
  "icon": "zigbee",
  "transport": { "type": "mqtt", "port": 1883 },
  "settings": [
    { "key": "friendlyName", "label": "Friendly name in Zigbee2MQTT", "help": "The name the device has in Zigbee2MQTT, such as hallway_sensor.\nOpen the Zigbee2MQTT web page, then Devices, and copy the name shown in the list." },
    { "key": "baseTopic", "label": "Base topic, zigbee2mqtt unless changed", "help": "The topic Zigbee2MQTT sends on. Leave it empty for zigbee2mqtt, unless you changed base_topic in its configuration." },
    { "key": "username", "label": "Broker user", "help": "The user name your MQTT broker asks for. Leave it empty if the broker takes anyone. It is in the broker's settings, for example the Mosquitto add-on's Logins in Home Assistant." },
    { "key": "password", "label": "Broker password (one per broker and user, shared by its devices)", "secret": true, "help": "The password for the broker user. It stays on this phone and is never shown again. Leave it empty if the broker has no password." }
  ],
  "setup": ["configure:friendlyName", "configure:baseTopic?", "configure:username?", "secret:password?"],
  "statePush": {
    "topics": [{ "topic": "{{device.baseTopic|'zigbee2mqtt'}}/{{device.friendlyName}}" }],
    "refresh": { "topic": "{{device.baseTopic|'zigbee2mqtt'}}/{{device.friendlyName}}/get", "payload": { "state": "" } }
  },
  "reliability": { "timeoutMs": 3000, "retries": 0 },
  "capabilities": [
    {
      "id": "power",
      "type": "toggle",
      "label": "Power",
      "onOff": ["ON", "OFF"],
      "command": { "topic": "{{device.baseTopic|'zigbee2mqtt'}}/{{device.friendlyName}}/set", "payload": { "state": "{{value}}" } },
      "stateJsonPath": "$.state"
    },
    {
      "id": "brightness",
      "type": "level",
      "label": "Brightness",
      "params": { "value": { "type": "number", "integer": true, "min": 0, "max": 254 } },
      "command": { "topic": "{{device.baseTopic|'zigbee2mqtt'}}/{{device.friendlyName}}/set", "payload": { "brightness": "{{value}}" } },
      "stateJsonPath": "$.brightness"
    },
    { "id": "temperature", "type": "sensor", "label": "Temperature", "stateJsonPath": "$.temperature" },
    { "id": "humidity", "type": "sensor", "label": "Humidity", "stateJsonPath": "$.humidity" },
    { "id": "occupancy", "type": "sensor", "label": "Motion", "stateJsonPath": "$.occupancy" },
    { "id": "contact", "type": "sensor", "label": "Contact (closed)", "stateJsonPath": "$.contact" },
    { "id": "battery", "type": "sensor", "label": "Battery", "stateJsonPath": "$.battery" }
  ]
}
''',
};
